const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Beira and Manga, Mozambique location
  const location = ee.Geometry.Point([34.8, -19.8]);
  const buffer = 25000; // 25km buffer for analysis area
  const geometry = location.buffer(buffer);

  // Define dates
  const date1 = ee.Date('2019-03-09');
  const date2 = ee.Date('2019-03-24');

  // Use VIIRS DNB nighttime lights data
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1_NOAA_CLASS');

  // Filter for March 2019 - collect all available data for that month
  const marchCollection = viirs.filter(ee.Filter.date('2019-03-01', '2019-03-31'));

  print("March 2019 VIIRS Images: " + marchCollection.size().getInfo());

  if (marchCollection.size().getInfo() === 0) {
    print("C1: No VIIRS data available for March 2019");
    return;
  }

  // Get the monthly composite for March 2019 (typically one image per month)
  const marchImage = marchCollection.first();

  // Extract the average radiance band
  const avgRad = marchImage.select('avg_rad');

  // Calculate statistics for the study region
  const stats = avgRad.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9
  });

  const meanRadiance = stats.get('avg_rad').getInfo();
  const pixelCount = avgRad.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  print("Pixel Count (March): " + pixelCount);
  print("Mean Radiance (March 2019): " + meanRadiance);

  // Check for valid data
  if (pixelCount === 0) {
    print("C2: No valid pixels in analysis region");
    return;
  }

  if (meanRadiance === null || meanRadiance === undefined || isNaN(meanRadiance)) {
    print("C3: Invalid radiance value (NaN or null)");
    return;
  }

  // Note: Since we only have monthly data, both March 9 and March 24 fall within
  // the same monthly composite. We cannot distinguish between the two specific dates
  // with monthly data. However, the question asks about intensity comparison.
  // With monthly VIIRS, both dates would use the same composite image.

  // For a more precise answer, we would need daily data if available.
  // Let's try VIIRS daily DNB data instead
  const viirsDaily = ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V1_NOAA_CLASS');

  // Filter for the specific dates
  const img1 = viirsDaily.filter(ee.Filter.date('2019-03-09', '2019-03-10'));
  const img2 = viirsDaily.filter(ee.Filter.date('2019-03-24', '2019-03-25'));

  print("March 9 Images: " + img1.size().getInfo());
  print("March 24 Images: " + img2.size().getInfo());

  if (img1.size().getInfo() === 0 || img2.size().getInfo() === 0) {
    print("C1: Missing data for one or both comparison dates");
    return;
  }

  // Get mean radiance for each date
  const img1Data = img1.first().select('avg_rad').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9
  });

  const img2Data = img2.first().select('avg_rad').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9
  });

  const radiance1 = img1Data.get('avg_rad').getInfo();
  const radiance2 = img2Data.get('avg_rad').getInfo();

  const count1 = img1.first().select('avg_rad').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const count2 = img2.first().select('avg_rad').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  print("March 9: Radiance=" + (radiance1 !== null ? radiance1.toFixed(3) : "null") + ", Pixels=" + count1);
  print("March 24: Radiance=" + (radiance2 !== null ? radiance2.toFixed(3) : "null") + ", Pixels=" + count2);

  // Validation
  if (count1 === 0 || count2 === 0) {
    print("C2: No valid pixels after filtering");
    return;
  }

  if (radiance1 === null || radiance2 === null || isNaN(radiance1) || isNaN(radiance2)) {
    print("C3: Invalid radiance calculation (NaN or null)");
    return;
  }

  // Compare: Was March 24 lower than March 9?
  if (radiance2 < radiance1) {
    print("Answer: Yes, nighttime light intensity was lower on March 24 than March 9");
    print("A");
  } else {
    print("Answer: No, nighttime light intensity was not lower on March 24 compared to March 9");
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
